const N8N_BASE_URL = "https://n8n.miabuilder.com";

const data = $input.first().json;

return [{
  json: {
    n8nBaseUrl: N8N_BASE_URL,
    executionId: data.execution?.id || '',
    workflowId: data.workflow?.id || '',
    workflowName: data.workflow?.name || '',
    errorMessage: data.execution?.error?.message || 'Erro desconhecido',
    nodeFalhou: data.execution?.lastNodeExecuted || 'desconhecido',
    executionUrl: data.execution?.url || ''
  }
}];

// =========================================================
// Localiza o registro (notificacao OU multa) que estava sendo
// gerado quando o fluxo 2.2 ou 2.4 quebrou, varrendo o runData
// da execucao que falhou.
// =========================================================

const CALLBACK_NOTIFICACAO =
  'https://monteiroramalho.getmia.com.br/api/public/n8n-notificacao-callback';
const CALLBACK_MULTA =
  'https://monteiroramalho.getmia.com.br/api/public/n8n-multa-callback';

const UUID_RE =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

// Nos onde o id costuma aparecer primeiro, em ordem de confianca.
// Os nomes de no sao iguais nos dois fluxos (Organiza os dados,
// Retorno para o sistema, Webhook); so muda o campo que carregam.
const NOS_NOTIFICACAO = ['Organiza os dados', 'id_notificacao', 'Cria notificação no sistema', 'Retorno para o sistema', 'Webhook'];
const NOS_MULTA = ['Organiza os dados', 'multa_id', 'Cria multa no sistema', 'Retorno para o sistema', 'Webhook'];

function buscaChave(obj, chaves, depth = 0) {
  if (!obj || typeof obj !== 'object' || depth > 12) return null;
  for (const chave of chaves) {
    const v = obj[chave];
    if (typeof v === 'string' && v.trim() !== '') return v.trim();
    if (typeof v === 'number') return String(v);
  }
  for (const key of Object.keys(obj)) {
    const achou = buscaChave(obj[key], chaves, depth + 1);
    if (achou) return achou;
  }
  return null;
}

function coletaItens(runData) {
  const out = [];
  for (const nodeName of Object.keys(runData)) {
    for (const run of (runData[nodeName] || [])) {
      for (const branch of (run?.data?.main || [])) {
        for (const item of (branch || [])) {
          if (item && item.json) out.push({ node: nodeName, json: item.json });
        }
      }
    }
  }
  return out;
}

function buscaPorPrioridade(itens, nosPrioritarios, chaves) {
  for (const nome of nosPrioritarios) {
    for (const it of itens) {
      if (it.node !== nome) continue;
      const achado = buscaChave(it.json, chaves);
      if (achado && UUID_RE.test(achado)) return achado;
    }
  }
  // fallback: procura em qualquer no, caso os nomes acima nao batam
  for (const it of itens) {
    const achado = buscaChave(it.json, chaves);
    if (achado && UUID_RE.test(achado)) return achado;
  }
  return null;
}

const prev = $('Extrai Dados do Erro').first().json;

let runData = {};
try {
  runData = $input.first().json?.data?.resultData?.runData || {};
} catch (e) {
  runData = {};
}

const itens = coletaItens(runData);

// Tenta achar um notificacao_id; se nao achar, tenta um multa_id.
// Os dois tipos de chave nunca aparecem no mesmo fluxo, entao nao
// ha risco de confundir um com o outro.
let tipo = null;
let registroId = buscaPorPrioridade(itens, NOS_NOTIFICACAO, ['notificacao_id', 'id_notificacao']);
if (registroId) {
  tipo = 'notificacao';
} else {
  registroId = buscaPorPrioridade(itens, NOS_MULTA, ['multa_id']);
  if (registroId) tipo = 'multa';
}

const CONFIG_POR_TIPO = {
  notificacao: { idFieldName: 'notificacao_id', callbackPadrao: CALLBACK_NOTIFICACAO, tipoLabel: 'notificação de infração', tipoLabelCap: 'Notificação' },
  multa:       { idFieldName: 'multa_id',       callbackPadrao: CALLBACK_MULTA,       tipoLabel: 'multa de infração',       tipoLabelCap: 'Multa' },
};
const cfg = tipo ? CONFIG_POR_TIPO[tipo] : { idFieldName: '', callbackPadrao: '', tipoLabel: 'registro', tipoLabelCap: 'Registro' };

// ---------- contexto para a mensagem da equipe ----------
function buscaEmTodos(chaves) {
  for (const it of itens) {
    const achado = buscaChave(it.json, chaves);
    if (achado) return achado;
  }
  return null;
}

const nomeCondominio = buscaEmTodos(['nome_condominio']) || '';
const bloco = buscaEmTodos(['numero_bloco', 'bloco']) || '';
const unidade = buscaEmTodos(['numero_unidade', 'unidade']) || '';
const origem = buscaEmTodos(['origem']) || '';
const telefone = buscaEmTodos(['botPhoneNumber', 'telefone']) || '';

const unidadeLabel = [
  bloco ? `Bloco ${bloco}` : null,
  unidade ? `Unidade ${unidade}` : null
].filter(Boolean).join(' / ') || '';

// ---------- url de callback ----------
let callbackUrl = buscaEmTodos(['callback_url']) || '';
if (!/^https?:\/\//i.test(callbackUrl)) callbackUrl = cfg.callbackPadrao;

// ---------- mensagem gravada no n8n_error do app ----------
const erroCallback = `[${prev.nodeFalhou}] ${prev.errorMessage} (execução ${prev.executionId})`
  .slice(0, 1500);

return [{
  json: {
    ...prev,
    tipo: tipo || '',
    tipoLabel: cfg.tipoLabel,
    tipoLabelCap: cfg.tipoLabelCap,
    idFieldName: cfg.idFieldName,
    registroId: registroId || '',
    temRegistro: !!registroId,
    callbackUrl,
    nomeCondominio,
    unidadeLabel,
    origem,
    telefone,
    erroCallback
  }
}];

